#!/bin/sh
# T46: point libpulse clients at the socket that actually exists. The
# pipewire snap's pipewire-pulse is socket-activated with its
# listen-stream generated by snapd at the SNAP-PRIVATE path
# (%t/snap.pipewire/pulse/native), and in greeter/wizard sessions
# nothing ever binds the conventional /run/user/<uid>/pulse/native
# (the hardlink bridge to the private socket exists only in real user
# sessions), so the previous unconditional export left every
# launcher-spawned pulse client (gsd-media-keys, gnome-shell) failing
# with "Failed to connect context: Connection refused" at the greeter.
# Prefer the conventional path when it exists (user sessions), fall
# back to the snap-private path (always bound by the socket unit).
_pulse_uid=`id -u`
if [ -S "/run/user/$_pulse_uid/pulse/native" ]; then
	export PULSE_SERVER=unix:/run/user/$_pulse_uid/pulse/native
else
	export PULSE_SERVER=unix:/run/user/$_pulse_uid/snap.pipewire/pulse/native
fi

. "$SNAP/fontconfig-env.sh" || exit 1
. "$SNAP/gdk-pixbuf-env.sh" || exit 1

case "$1" in
	/usr/*)
		content_command="$SNAP/gnome$1"
		if [ -x "$content_command" ]; then
			shift
			set -- "$content_command" "$@"
		fi
		;;
esac

# The screencast entry point is a GJS module rather than an executable.
if [ "$1" = "$SNAP/gnome/usr/bin/gjs" ] &&
	[ "$2" = "-m" ] &&
	[ "$3" = "/usr/share/gnome-shell/org.gnome.Shell.Screencast" ]; then
	gjs_command="$1"
	shift
	gjs_mode="$1"
	shift
	shift
	. "$SNAP/screencast-env.sh" || exit 1
	set -- "$gjs_command" "$gjs_mode" "$GNOME_SHELL_SCREENCAST_ENTRY" "$@"
fi

# WAYLAND_DISPLAY is normally a bare socket name (e.g. "wayland-0") that
# clients resolve relative to $XDG_RUNTIME_DIR. `snap run` always
# privatizes XDG_RUNTIME_DIR to a per-snap subdirectory
# (/run/user/<uid>/snap.<name>/) for this app, but the compositor
# (gnome-shell, started directly by systemd rather than via `snap run`)
# creates its socket under the real, unprivatized
# /run/user/<uid>/wayland-N. Rewrite a relative WAYLAND_DISPLAY to an
# absolute path pointing at the real socket so clients in this snap can
# still find it; libwayland treats an absolute WAYLAND_DISPLAY as a
# literal socket path instead of resolving it against XDG_RUNTIME_DIR.
case "$WAYLAND_DISPLAY" in
	/*|"") ;;
	*) export WAYLAND_DISPLAY="/run/user/`id -u`/$WAYLAND_DISPLAY" ;;
esac

# T53: the shell IS mutter -- it validates /tmp/.X11-unix inside this
# snap's shared private tmp when it spawns Xwayland (mutter
# ensure_x11_unix_perms: the dir must be owned by /tmp's uid or by us,
# be sticky+writable, else the shell SIGABRTs "Failed to start X
# Wayland: Wrong ownership"). Heal it once, before the compositor
# launches. This branch covers ALL session kinds: the wizard, greeter
# and user shells all dispatch through this app (@initial-setup/@gdm/
# @ubuntu -> gnome-content-launch --session-dispatch gnome-shell ->
# /snap/bin/ubuntu-desktop-session.gnome-shell -> here). See
# ensure-x11-dir.sh for the full rationale; the ensure-x11-dir oneshot
# service is the boot-time root pass that makes the dir root-owned
# (acceptable to every uid) before any session starts.
if [ "$1" = "$SNAP/gnome/usr/bin/gnome-shell" ]; then
	"$SNAP/ensure-x11-dir.sh" || true
fi

if [ "$1" = "$SNAP/gnome/usr/bin/gnome-shell" ] || [ "$1" = "$SNAP/gnome/usr/libexec/xdg-desktop-portal-gnome" ]; then
	# Avoid synchronous portal lookups while Shell and its backend start.
	export GIO_USE_MEMORY_MONITOR=poll
fi

if [ "$1" = "$SNAP/gnome/usr/libexec/xdg-desktop-portal-gnome" ]; then
	"$SNAP/gnome/usr/bin/gjs-console" "$SNAP/wait-for-mutter-service-channel.js" || exit 1
fi

exec "$@"
